dst=r'C:\NYP\VisualStudio\Testing ground\ShopSphere\docs\IT2226_ShopSphere_Brief_Student.md'
W='{http://schemas.openxmlformats.org/wordprocessingml/2006/main}'
ns={'w':W[1:-1]}
with zipfile.ZipFile(src) as z:
    root=ET.fromstring(z.read('word/document.xml'))
body=root.find('w:body',ns)

def text_of(el):
    return ''.join(t.text or '' for t in el.findall('.//w:t',ns)).strip()

def para_style(p):
    st=p.find('w:pPr/w:pStyle',ns)
    return st.get(W+'val') if st is not None else ''

def para_md(p):
    style=para_style(p); txt=text_of(p)
    if not txt: return ''
    esc=lambda s: s.replace('|','\\|').replace('\n',' ').strip()
    if style in ('Title','Heading1'):
        return '# '+esc(txt)
    if style=='Heading2':
        return '## '+esc(txt)
    if style=='Heading3':
        return '### '+esc(txt)
    if style=='ListBullet':
        return '- '+esc(txt)
    if style=='ListNumber':
        return '1. '+esc(txt)
    return esc(txt)

def table_md(tbl):
    rows=tbl.findall('w:tr',ns)
    parsed=[]
    for tr in rows:
        cells=[]
        for tc in tr.findall('w:tc',ns):
            paras=[text_of(p) for p in tc.findall('w:p',ns)]
            cells.append('<br>'.join(x for x in paras if x).replace('|','\\|'))
        parsed.append(cells)
    if not parsed: return ''
    if len(parsed)==1 and len(parsed[0])==1:
        return '\n'.join('> '+line if line else '>' for line in parsed[0][0].split('<br>'))
    width=max(len(r) for r in parsed)
    parsed=[r+['']*(width-len(r)) for r in parsed]
    out=['| '+' | '.join(parsed[0])+' |','| '+' | '.join(['---']*width)+' |']
    out += ['| '+' | '.join(r)+' |' for r in parsed[1:]]
    return '\n'.join(out)

parts=[]
for child in body:
    tag=child.tag.split('}')[-1]
    if tag=='p':
        md=para_md(child)
        if md: parts.append(md)
    elif tag=='tbl':
        md=table_md(child)
        if md: parts.append(md)
md='\n\n'.join(parts).strip()+'\n'
with open(dst,'w',encoding='utf-8',newline='\n') as f:
    f.write(md)
print('wrote', dst, len(md), 'chars')
